# Create the sub-server with math tools
math_server = FastMCP("Math Server")

@math_server.tool
def add(a: float, b: float) -> float:
    """Add two numbers."""
    return a + b

@math_server.tool
def multiply(a: float, b: float) -> float:
    """Multiply two numbers."""
    return a * b

@math_server.tool
def divide(a: float, b: float) -> float:
    """Divide two numbers."""
    if b == 0:
        raise ValueError("Cannot divide by zero")
    return a / b

# Create the main server
main_server = FastMCP("Main Server")

@main_server.tool
def hello(name: str) -> str:
    """Greet someone."""
    return f"Hello, {name}!"

# Mount the math server under the "math" prefix
main_server.mount(math_server, namespace="math")

